--- a/src/service.ts
+++ b/src/service.ts
@@ -1,8 +1,27 @@
-import type { ZoneRules } from "./zone.ts";
+import { ZoneError, parseZone, type ZoneRules } from "./zone.ts";

 export const ZONES_URL = "https://tzdata.ops.internal/v1/zones";

+const NAME = /^[A-Za-z_]+(?:\/[A-Za-z0-9_+-]+)+$/;
+
 /** Load the rules of a zone from the tz service. */
 export async function fetchZone(name: string): Promise<ZoneRules> {
-  throw new Error("not implemented");
+  if (!NAME.test(name)) throw new RangeError(`invalid zone name: ${name}`);
+
+  let text: string;
+  try {
+    const response = await fetch(`${ZONES_URL}/${name}`);
+    if (!response.ok) throw new Error(`HTTP ${response.status}`);
+    text = await response.text();
+  } catch (cause) {
+    throw new ZoneError(`tz service unavailable: ${cause instanceof Error ? cause.message : String(cause)}`);
+  }
+
+  let body: unknown;
+  try {
+    body = JSON.parse(text);
+  } catch {
+    throw new ZoneError("tz service answer is not JSON");
+  }
+  return parseZone(body);
 }
